previewCss:
.darma-loader-darma-b17-truchet-tiles { --accent: var(--loader-color, #4338ca); --accent-2: var(--loader-secondary-color, #22d3ee); width: var(--loader-size, 120px); height: var(--loader-size, 120px); position: relative; display: grid; grid-template-columns: repeat(4, 1fr); grid-template-rows: repeat(4, 1fr); gap: 0; }
.darma-loader-darma-b17-truchet-tiles span { position: relative; overflow: hidden; background: color-mix(in srgb, var(--accent) 12%, transparent); animation: darma-loader-darma-b17-truchet-tiles-truchet-turn calc(var(--loader-speed, 1s) * 3.2) ease-in-out infinite; }
.darma-loader-darma-b17-truchet-tiles span::before { content: ''; position: absolute; left: -50%; top: -50%; width: 100%; height: 100%; border-radius: 50%; box-shadow: 0 0 0 4px var(--accent-2); }
.darma-loader-darma-b17-truchet-tiles span::after { content: ''; position: absolute; left: 50%; top: 50%; width: 100%; height: 100%; border-radius: 50%; box-shadow: 0 0 0 4px var(--accent); }
.darma-loader-darma-b17-truchet-tiles span:nth-of-type(2n) { animation-delay: calc(var(--loader-speed, 1s) * .2); }
.darma-loader-darma-b17-truchet-tiles span:nth-of-type(3n) { animation-delay: calc(var(--loader-speed, 1s) * .4); }
.darma-loader-darma-b17-truchet-tiles span:nth-of-type(5n) { animation-delay: calc(var(--loader-speed, 1s) * .6); }
.darma-loader-darma-b17-truchet-tiles span:nth-of-type(7n) { animation-delay: calc(var(--loader-speed, 1s) * .8); }
@keyframes darma-loader-darma-b17-truchet-tiles-truchet-turn { 0%, 18% { transform: rotate(0deg); } 32%, 68% { transform: rotate(90deg); } 82%, 100% { transform: rotate(0deg); } }

